<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { ArrowUpRight, ClipboardCheck, Bell, TrendingUp, ShieldCheck, RefreshCw } from 'lucide-vue-next';
import { authRequest, currentUser, hasPermission } from '../auth';
import { canOpenPage } from '../access';
import type { V2Task } from '../v2/types';
import type { V3Alert,V3Improvement } from '../v3/types';
const emit=defineEmits<{navigate:[page:string]}>();
const data=ref<{tasks:V2Task[];alerts:V3Alert[];improvements:V3Improvement[];stats:Record<string,number>}|null>(null);
const loading=ref(false),error=ref('');
const shortcuts=computed(()=>[{id:'workbench',name:'评审作业台',text:'条款、任务与材料审核'},{id:'v3',name:'指标与整改',text:'数据监测及质量改进'},{id:'manual',name:'补录申请',text:'提交并跟踪人工补录'},{id:'accounts',name:'账号管理',text:'维护本院账号及授权'},{id:'operations',name:'审计记录',text:'查看本院操作轨迹'}].filter(s=>canOpenPage(s.id)));
async function load(){loading.value=true;error.value='';try{data.value=await authRequest('/workbench');}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
onMounted(load);
</script>
<template><div class="personal-workbench"><section class="welcome-card"><div><span class="eyebrow">MY WORKSPACE</span><h2>{{currentUser?.displayName}}，欢迎回来</h2><p>{{currentUser?.roleName}} · {{currentUser?.deptName||currentUser?.hospitalName}}</p><span class="subtle-tag"><ShieldCheck :size="13"/> 仅显示当前账号授权范围内的数据</span></div><button class="button" :disabled="loading" @click="load"><RefreshCw :size="15"/>刷新待办</button></section>
<div v-if="error" class="error-box" role="alert">{{error}}</div><p v-if="loading&&!data" class="empty">正在读取授权待办…</p>
<template v-if="data"><div class="home-stats"><div v-if="data.stats.accounts != null" class="card"><ShieldCheck :size="20"/><strong>{{data.stats.accounts}}</strong><span>本院账号</span></div><div v-if="hasPermission('task.read')" class="card"><ClipboardCheck :size="20"/><strong>{{data.stats.openTasks}}</strong><span>未完成条款任务</span></div><div v-if="hasPermission('alert.read')" class="card"><Bell :size="20"/><strong>{{data.stats.openAlerts}}</strong><span>待跟踪预警</span></div><div v-if="hasPermission('improvement.read')" class="card"><TrendingUp :size="20"/><strong>{{data.stats.openImprovements}}</strong><span>进行中整改</span></div></div>
<section class="card"><div class="section-heading"><h3>快捷入口</h3><span class="hint">按当前权限开放</span></div><div class="home-shortcuts"><button v-for="s in shortcuts" :key="s.id" @click="emit('navigate',s.id)"><strong>{{s.name}}<ArrowUpRight :size="16"/></strong><small>{{s.text}}</small></button></div></section>
<section v-if="hasPermission('task.read')" class="card table-card"><div class="section-heading"><h3>我的条款任务</h3><button v-if="data.tasks.length" class="text-button" @click="emit('navigate','workbench')">进入任务台 →</button></div><div class="table-wrap"><table><thead><tr><th>条款</th><th>任务</th><th>科室</th><th>状态</th><th>截止日期</th></tr></thead><tbody><tr v-for="t in data.tasks.slice(0,10)" :key="t.id"><td>{{t.clauseCode}}</td><td>{{t.title}}</td><td>{{t.deptCode}}</td><td><span class="badge">{{({todo:'待处理',in_progress:'处理中',submitted:'待审核',accepted:'已受理',returned:'已退回',cancelled:'已取消'} as Record<string,string>)[t.status]||t.status}}</span></td><td>{{t.dueDate}}</td></tr><tr v-if="!data.tasks.length"><td colspan="5" class="empty">当前授权范围内暂无条款任务</td></tr></tbody></table></div></section>
<div v-if="hasPermission('alert.read') || hasPermission('improvement.read')" class="home-columns"><section v-if="hasPermission('alert.read')" class="card"><div class="section-heading"><h3>预警跟踪</h3></div><div v-for="a in data.alerts.slice(0,5)" :key="a.id" class="home-row"><strong>{{a.metricName}}</strong><small>{{a.deptCode}} · {{a.period}} · {{a.detail}}</small></div><p v-if="!data.alerts.length" class="empty">当前授权范围内暂无预警</p></section><section v-if="hasPermission('improvement.read')" class="card"><div class="section-heading"><h3>持续改进</h3></div><div v-for="i in data.improvements.slice(0,5)" :key="i.id" class="home-row"><strong>{{i.metricName||i.id}}</strong><small>{{i.owner}} · {{i.status}} · {{i.dueDate}}</small></div><p v-if="!data.improvements.length" class="empty">当前授权范围内暂无整改项目</p></section></div></template></div></template>
